def esc(value: str) -> str:
    return value.replace("\\", "\\\\").replace("'", "''")

def validate():
    errors = []
    domain_names = [d for d, _ in DOMAINS]
    if len(domain_names) != len(set(domain_names)):
        errors.append("duplicate domain")

    career_names = [c[1] for c in CAREERS]
    if len(career_names) != len(set(career_names)):
        errors.append("duplicate career")

    skill_pairs = set()
    all_skills = set()

    for domain, career, description, average_level, requirements in CAREERS:
        if domain not in set(domain_names):
            errors.append(f"unknown domain: {domain}")
        if average_level not in {"Beginner", "Intermediate", "Advanced"}:
            errors.append(f"invalid average_level for {career}")
        if not requirements:
            errors.append(f"career has no skills: {career}")

        local = set()
        for skill, level in requirements:
            if skill in local:
                errors.append(f"duplicate skill in {career}: {skill}")
            local.add(skill)
            all_skills.add(skill)
            if not 1 <= int(level) <= 100:
                errors.append(f"invalid required level: {career} / {skill}")
            pair = (career, skill)
            if pair in skill_pairs:
                errors.append(f"duplicate career-skill mapping: {career} / {skill}")
            skill_pairs.add(pair)

    if errors:
        raise SystemExit("\n".join(["VALIDATION FAILED:"] + ["- " + e for e in errors]))

    print("Validation passed.")
    print(f"Domains: {len(domain_names)}")
    print(f"Careers: {len(career_names)}")
    print(f"Canonical skills used: {len(all_skills)}")
    print(f"Career-skill mappings: {len(skill_pairs)}")
    print(f"Programs: {len(PROGRAMS)}")

